# wowf map image -> minimap pixels (absolute: tile x * 512 + px), fitted by
# matching the wowf images against the stitched tiles (SIFT for the two
# minimap screenshots, edge matching for the Hall of Thanes render):
# (image width, image height, scale, x offset, y offset)
FIT = {
 'excavation-site':    (1100, 1017, 1.5602, 33 * 512 + 716.0, 36 * 512 + 819.3),
 'ruins-of-lordaeron': (1100, 1251, 0.5028, 30 * 512 + 521.9, 27 * 512 + 690.9),
 'hall-of-thanes':     (1366, 1500, 0.3350, 27 * 512 + 2337.0, 25 * 512 + 3197.0),
}

# shown part of each minimap (absolute px: x, y, w, h)
VIEW = {
 'hall-of-thanes':     (16125, 15772, 535, 739),
 'excavation-site':    (17836, 19782, 1000, 620),
 'ruins-of-lordaeron': (15860, 14494, 600, 670),
 'dalaran':            (15808, 15858, 580, 670),
}

# Dalaran has no wowf map: spots placed by the guide's area names
# (sewers under the south-east pit, Round Terrace, Fel Grove, Magus Commerce
# Exchange, Violet Citadel in the north). Absolute px.
_D = 29 * 512
DALARAN = {"start": (_D + 1405, _D + 1606), 1: (_D + 1352, _D + 1645), 7: (_D + 1455, _D + 1648),
           2: (_D + 1330, _D + 1460), 3: (_D + 1405, _D + 1300), 4: (_D + 1210, _D + 1300), 9: (_D + 1150, _D + 1100)}


def to_px(slug, pos):
    """wowf % position -> absolute minimap px."""
    w, h, s, ox, oy = FIT[slug]
    return (ox + pos[0] * w / 100 * s, oy + pos[1] * h / 100 * s)
